package com.wandertrace.service; import com.wandertrace.dto.PublicMemoryResponse; import com.wandertrace.exception.NotFoundException; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class PublicMemoryService {private final JdbcTemplate db; public PublicMemoryService(JdbcTemplate db){this.db=db;} @Transactional public PublicMemoryResponse find(String token){var rows=db.queryForList("select m.title,m.subtitle,m.story,m.memory_date,d.name destination,d.country,coalesce(cm.url,d.cover_image_url) cover from nfc_tags n join memories m on n.memory_id=m.id join destinations d on m.destination_id=d.id left join media cm on m.cover_media_id=cm.id where n.token=? and n.active=true and m.visibility='PUBLIC'",token);if(rows.isEmpty())throw new NotFoundException("Memory not found");db.update("update nfc_tags set scan_count=scan_count+1,last_scanned_at=now(),updated_at=now() where token=?",token);var r=rows.getFirst();var media=db.queryForList("select id,type,url,thumbnail_url,title,caption from media where memory_id=(select memory_id from nfc_tags where token=?) order by sort_order",token);List<PublicMemoryResponse.Media> all=media.stream().map(x->new PublicMemoryResponse.Media(x.get("id").toString(),x.get("type").toString(),(String)x.get("url"),(String)x.get("thumbnail_url"),(String)x.get("title"),(String)x.get("caption"))).toList();var loc=db.queryForList("select name,description,latitude,longitude,visited_at from locations where memory_id=(select memory_id from nfc_tags where token=?) order by sort_order",token).stream().map(x->new PublicMemoryResponse.Location((String)x.get("name"),(String)x.get("description"),((Number)x.get("latitude")).doubleValue(),((Number)x.get("longitude")).doubleValue(),toDateTime(x.get("visited_at")))).toList();var timeline=db.queryForList("select title,description,event_time from timeline_events where memory_id=(select memory_id from nfc_tags where token=?) order by sort_order",token).stream().map(x->new PublicMemoryResponse.Timeline((String)x.get("title"),(String)x.get("description"),(String)x.get("event_time"))).toList();return new PublicMemoryResponse((String)r.get("title"),(String)r.get("subtitle"),(String)r.get("story"),toDate(r.get("memory_date")),(String)r.get("destination"),(String)r.get("country"),(String)r.get("cover"),all.stream().filter(m->m.type().equals("IMAGE")).toList(),all.stream().filter(m->m.type().equals("VIDEO")).toList(),all.stream().filter(m->m.type().equals("AUDIO")).toList(),loc,timeline,List.of("night walk","first visit","paris"));} private LocalDate toDate(Object value){return value instanceof LocalDate date?date:((java.sql.Date)value).toLocalDate();} private LocalDateTime toDateTime(Object value){return value instanceof LocalDateTime dateTime?dateTime:((java.sql.Timestamp)value).toLocalDateTime();}}
